using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
    const int UnitReplyCheckpoints=12;
    bool ReplyMoved=>FlowCase=="reply-moved"||FlowCase is "held-report" or "held-open" or "evidence-unit";
    async Task UnitReplyStep(int n){await Frame();var s=game!.Session;
        if(n==1){if(ReplyMoved){game.ChooseMilitary(NewMilitaryAction.CombatPermit);game.Advance(s.Seconds+2);OpenAllServiceLetters();}var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExerciseMilitaryLine(new(a.X+(ReplyMoved?5000:20000),a.Y+(ReplyMoved?0:-12000)),new(a.X+(ReplyMoved?5000:20000),a.Y+(ReplyMoved?10000:12000)));game.Advance(ArmyEnd()+1);}
        if(n==2){if(ReplyMoved)game.ChooseMilitary(NewMilitaryAction.CombatStart);game.ChooseMilitary(NewMilitaryAction.Handoff);game.ChooseMilitary(NewMilitaryAction.Withdraw);game.Press("military-frame");}
        if(n==3)game.Advance(PersonalEnd()+1);
        if(n==4){if(ReplyMoved){var w=s.DiagnosticSnapshot();long start=w.NewMilitary!.Requests.Single(q=>q.Input.Action==NewMilitaryAction.CombatStart).At;var known=w.NewMilitary.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);Check(start+9-delay>=s.Seconds,"fixture returns home before pre-rout query window");game.Advance(start+9-delay);}game.ChooseMilitary(NewMilitaryAction.InquireUnitKnown);Check(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!=null,"normal new inquiry explicitly records reply recovery policy");}
        if(n==5){game.Advance(CurrentInquiry().DueAt);Check(CurrentInquiryReply().Delivered,"unit physically receives query before moving");var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);game.ExercisePersonalMove(new(home.X+5000,home.Y));}
        if(n==6){game.Advance(CurrentInquiryReply().ReplyDueAt);var w=s.DiagnosticSnapshot();var r=CurrentInquiryReply();Check(!w.NewMilitary!.UnitInquiry!.Replies.Last().Received&&!MessageFlow.FailureKnown(w.Messaging,r.ReplyAttempt,NewGameMilitary.UnitIds[0].Value),"missing person causes initial reply loss without remote failure recognition");Check(w.NewMilitary.ReplyRecovery!.Flights.Single().Kind==UnitReplyLeg.FailureReport,"same carrier starts a physical return with failure report");}
        if(n==7){if(!ReplyMoved)game.ChooseMilitary(NewMilitaryAction.PersonalHome);}
        if(n==8){var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();game.Advance(report.DueAt);if(!ReplyMoved)game.Advance(s.Seconds+1);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.ReplyRecovery!;if(ReplyMoved){Check(!x.Arrivals.Single().Delivered&&x.Holdings.Length==2,"moved receiver never learns failure; courier retains both reply and unreceived report");Check(w.Messaging.Attempts.Count(a=>a.MessageId==CurrentInquiryReply().ReplyMessage)==1,"no omniscient retry after report missed old unit post");}else{Check(x.Arrivals.First().Delivered&&x.Holdings.Length==1&&x.Flights.Last().Kind==UnitReplyLeg.Retry,"only physical failure receipt authorizes a new reply attempt");var frames=NewGameMilitary.CourierFrames(w,s.Seconds);Check(frames.Length==2&&frames.Select(f=>f.Carrier).Distinct().Count()==2&&frames.Select(f=>f.Position).Distinct().Count()==2,"old retained original and fresh retry are distinct actual couriers");}}
        if(n==9){if(ReplyMoved){Check(NewGameMilitary.UnitInquiryStatus(s.DiagnosticSnapshot()).Contains("未受領"),"retained paper is not an automatic receipt");}else{var retry=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last();game.Advance(retry.DueAt);var w=s.DiagnosticSnapshot();var r=CurrentInquiryReply();Check(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value)&&w.Messaging.Receipts.Count(t=>t.MessageId==r.ReplyMessage)==1&&!w.NewMilitary!.UnitInquiry!.Replies.Last().Received,"same original reply arrives once while initial loss stays unchanged");}}
        if(n==10){if(ReplyMoved){game.ChooseMilitary(NewMilitaryAction.PersonalHome);game.Advance(Math.Max(PersonalEnd(),ArmyEnd())+1);var arrivals=s.DiagnosticSnapshot().NewMilitary!.Rout!.Arrivals;game.Advance(Math.Max(s.Seconds,arrivals.Max(a=>a.At)+NewGameMilitary.RegroupSeconds));}else{game.ChooseMilitary(NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();game.Advance(d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last();game.Advance(Math.Max(ArmyEnd()+1,r.ReplyDueAt));}}
        if(n==11){game.ChooseMilitary(NewMilitaryAction.Attach);game.ChooseMilitary(NewMilitaryAction.Reclaim);game.ChooseMilitary(NewMilitaryAction.Enter);game.ChooseMilitary(NewMilitaryAction.Unload);game.ChooseMilitary(NewMilitaryAction.Report);game.ChooseMilitary(NewMilitaryAction.Return);game.Advance(s.Seconds+3);OpenAllServiceLetters();Check(s.DiagnosticSnapshot().NewMilitary!.Events.Any(e=>e.Effect==MilitaryEffect.Returned),"same officer completes cargo and command return without transport resurrection");}
        game.Press("save");game.Refresh();
    }
    async Task BeginUnitReplyContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<UnitReplyCheckpoints;n++){await UnitReplyStep(n);game!.SaveCheckpoint("unitreply"+n);await Capture("s"+n,true);}await Capture("final",true);}
    async Task RestoreUnitReply(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,r=>r.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<UnitReplyCheckpoints;n++){game!.LoadCheckpoint("unitreply"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"actual independent carrier/holding/army pose restored at"+n);await Capture("restored-s"+n,true);for(int next=n+1;next<UnitReplyCheckpoints;next++)await UnitReplyStep(next);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same report/retry/retained-paper future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_REPLY_RESTORED "+n);}}
    async Task RunUnitReplyChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreUnitReply();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-reply-film")){game!.LoadCheckpoint("unitreply8");game.Press("auto");string dir=Path.Combine(TestOutput,"film");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"reply-"+n.ToString("D3")+".png"));}game.Press("pause");}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_REPLY_PASSED "+FlowCase);}
}
